/* Fontes embutidas (WOFF2 em base64, licença SIL OFL 1.1; textos em app/vendor/fonts/ e origem em app/vendor/README.md).
   Sem elas o texto do canvas cai na fonte do sistema e o mesmo projeto rende diferente em cada máquina.
   Registradas por FontFace a partir dos bytes, antes do motor: o primeiro quadro já usa a fonte certa. */
const VJ_FONTS = [
  { family: 'Archivo Black', weight: '100 900', stretch: '100%', d: '' },
  { family: 'Bebas Neue', weight: '100 900', stretch: '100%', d: '' },
  { family: 'Martian Mono', weight: '100 800', stretch: '75% 112.5%', d: '' }
];
const VJ_FONTS_READY = (() => {
  if (typeof FontFace === 'undefined' || !document.fonts) return Promise.resolve();
  return Promise.all(VJ_FONTS.map(f => { const b = Uint8Array.from(atob(f.d), ch => ch.charCodeAt(0)), ff = new FontFace(f.family, b, { weight: f.weight, stretch: f.stretch }); document.fonts.add(ff); return ff.load().catch(() => {}); }));
})();
